@verbatim
<dialog class="adapt-modal" id="changeModal" aria-labelledby="changeModal-title"><div class="modal-card"><div class="modal-head"><h3 id="changeModal-title">Report workplace change</h3><button aria-label="Close dialog" type="button" class="x" onclick="closeModal('changeModal')">×</button></div><div class="form-grid"><div><label for="chgType">Change type</label><select id="chgType"><option value="New work activity">New work activity</option><option value="New machinery/equipment">New machinery/equipment</option><option value="New chemical">New chemical</option><option value="New contractor">New contractor</option><option value="New worker / role">New worker / role</option><option value="Layout / workplace area">Layout / workplace area</option><option value="Incident / control failure">Incident / control failure</option></select></div><div><label for="chgArea">Area / department</label><input id="chgArea" value="Production Area B"></div></div><label for="chgDesc">Description</label><textarea id="chgDesc">New MIG welding activity introduced for fabrication work.</textarea><div class="toolbar"><span class="note">The Adapt Engine will identify linked modules requiring review.</span><button type="button" class="btn primary" onclick="analyseChange()">Analyse change</button></div></div></dialog>
<dialog class="adapt-modal" id="jmsModal" aria-labelledby="jmsModal-title"><div class="modal-card"><div class="modal-head"><h3 id="jmsModal-title">Create job method statement</h3><button aria-label="Close dialog" type="button" class="x" onclick="closeModal('jmsModal')">×</button></div><p class="note">Work with your technical team and workers to describe the actual sequence of work.</p><h4>1. Describe the work</h4><label for="jmsActivity">Activity / job name</label><input id="jmsActivity" placeholder="e.g. Inspecting a machine" required><label for="jmsPreparedBy">Prepared by</label><input id="jmsPreparedBy" placeholder="Name or technical team" required><div class="jms-builder-heading"><h4>2. Break the activity into job steps</h4><p class="note">Use one action per step, in the order it happens. Example: isolate the machine → inspect the guard → restore the machine.</p></div><div id="jmsStepBuilder"></div><button type="button" class="btn small" id="jmsAddStep">+ Add job step</button><textarea id="jmsSteps" hidden></textarea><div class="toolbar"><span></span><button type="button" class="btn primary" onclick="saveJMS()">Save JMS &amp; continue to assessment</button></div></div></dialog>
<dialog class="adapt-modal" id="hirarcModal" aria-labelledby="hirarcModal-title"><div class="modal-card"><div class="modal-head"><h3 id="hirarcModal-title">Add HIRARC row</h3><button aria-label="Close dialog" type="button" class="x" onclick="closeModal('hirarcModal')">×</button></div><div class="form-grid"><div><label for="hActivity">JMS job step</label><select id="hActivity" required></select></div><div><label for="hHazard">Hazard</label><input id="hHazard" placeholder="Describe the hazard"></div><div><label for="hL">Likelihood (1–5)</label><input id="hL" max="5" min="1" type="number" value="1"></div><div><label for="hS">Severity (1–5)</label><input id="hS" max="5" min="1" type="number" value="1"></div></div><label for="hControl">Existing / proposed controls</label><textarea id="hControl" placeholder="Describe the controls"></textarea><div class="toolbar"><span></span><button type="button" class="btn primary" onclick="addHirarc()">Calculate &amp; save</button></div></div></dialog>

<dialog class="adapt-modal" id="memberModal" aria-labelledby="memberModal-title"><div class="modal-card"><div class="modal-head"><h3 id="memberModal-title">Add committee member</h3><button aria-label="Close dialog" type="button" class="x" onclick="closeModal('memberModal')">×</button></div><div class="form-grid"><div><label for="mName">Name</label><input id="mName" value="Aina Rahman"></div><div><label for="mRole">Role</label><select id="mRole"><option value="Chairperson">Chairperson</option><option value="Secretary">Secretary</option><option value="Employer representative">Employer representative</option><option value="Employee representative">Employee representative</option></select></div></div><div class="toolbar"><span></span><button type="button" class="btn primary" onclick="addMember()">Add member</button></div></div></dialog>
<dialog class="adapt-modal" id="actionModal" aria-labelledby="actionModal-title"><div class="modal-card"><div class="modal-head"><h3 id="actionModal-title">New corrective action</h3><button aria-label="Close dialog" type="button" class="x" onclick="closeModal('actionModal')">×</button></div><div class="form-grid"><div><label for="aSource">Source</label><select id="aSource"><option value="HIRARC">HIRARC</option><option value="Incident">Incident</option><option value="Inspection">Inspection</option><option value="HRA">HRA</option><option value="Committee">Committee</option><option value="Audit">Audit</option><option value="OSHWA">OSHWA</option><option value="Adapt Engine">Adapt Engine</option><option value="Custom">Custom</option></select><label for="aSourceCustom">Custom source (when selected)</label><input id="aSourceCustom" placeholder="Enter custom source"></div><div><label for="aOwner">Owner</label><input id="aOwner" value="Safety Supervisor"></div><div><label for="aDue">Due</label><input id="aDue" type="date" value="2026-10-10"></div><div><label for="aText">Action</label><input id="aText" value="Install welding-screen separation in Area B"></div></div><div class="toolbar"><span></span><button type="button" class="btn primary" onclick="addAction()">Save action</button></div></div></dialog>
<dialog class="adapt-modal" id="workerModal" aria-labelledby="workerModal-title"><div class="modal-card"><div class="modal-head"><h3 id="workerModal-title">Add worker passport</h3><button aria-label="Close dialog" type="button" class="x" onclick="closeModal('workerModal')">×</button></div><div class="form-grid"><div><label for="wName">Name</label><input id="wName" value="Rafiq Hasan"></div><div><label for="wRole">Role</label><input id="wRole" value="Welder"></div><div><label for="wNat">Nationality</label><input id="wNat" value="Bangladesh"></div><div><label for="wWork">Assigned work</label><input id="wWork" value="Welding / fabrication"></div></div><div class="toolbar"><span></span><button type="button" class="btn primary" onclick="addWorker()">Create passport</button></div></div></dialog>
<dialog class="adapt-modal" id="equipmentModal" aria-labelledby="equipmentModal-title"><div class="modal-card"><div class="modal-head"><h3 id="equipmentModal-title">Add equipment</h3><button aria-label="Close dialog" type="button" class="x" onclick="closeModal('equipmentModal')">×</button></div><div class="form-grid"><div><label for="eqName">Asset</label><input id="eqName" value="MIG Welder 04"></div><div><label for="eqCat">Category</label><input id="eqCat" value="Welding equipment"></div><div><label for="eqArea">Area</label><input id="eqArea" placeholder="Work location"></div><div><label for="eqDate">Next inspection</label><input id="eqDate" type="date" value="2026-10-20"></div></div><div class="toolbar"><span></span><button type="button" class="btn primary" onclick="addEquipment()">Add equipment</button></div></div></dialog>
<dialog class="adapt-modal" id="chemicalModal" aria-labelledby="chemicalModal-title"><div class="modal-card"><div class="modal-head"><h3 id="chemicalModal-title">Add chemical</h3><button aria-label="Close dialog" type="button" class="x" onclick="closeModal('chemicalModal')">×</button></div><div class="form-grid"><div><label for="cName">Chemical / product</label><input id="cName" value="Paint thinner"></div><div><label for="cUse">Use</label><input id="cUse" value="Cleaning / coating"></div><div><label for="cSds">SDS available?</label><select id="cSds"><option value="Yes">Yes</option><option value="No">No</option></select></div><div><label for="cLabel">Label compliant?</label><select id="cLabel"><option value="Yes">Yes</option><option value="No">No</option></select></div></div><div class="toolbar"><span></span><button type="button" class="btn primary" onclick="addChemical()">Add chemical</button></div></div></dialog>
<dialog class="adapt-modal" id="trainingModal" aria-labelledby="trainingModal-title"><div class="modal-card"><div class="modal-head"><h3 id="trainingModal-title">Assign training</h3><button aria-label="Close dialog" type="button" class="x" onclick="closeModal('trainingModal')">×</button></div><div class="form-grid"><div><label for="tWho">Worker / role</label><input id="tWho" value="Welders"></div><div><label for="tWhat">Training</label><input id="tWhat" value="Welding safety / hot work briefing"></div><div><label for="tDue">Due</label><input id="tDue" type="date" value="2026-10-05"></div><div><label for="tStatus">Status</label><select id="tStatus"><option value="Assigned">Assigned</option><option value="Completed">Completed</option><option value="Overdue">Overdue</option></select></div></div><div class="toolbar"><span></span><button type="button" class="btn primary" onclick="addTraining()">Assign</button></div></div></dialog>
<dialog class="adapt-modal" id="ptwModal" aria-labelledby="ptwModal-title"><div class="modal-card"><div class="modal-head"><h3 id="ptwModal-title">Create Permit to Work</h3><button aria-label="Close dialog" type="button" class="x" onclick="closeModal('ptwModal')">×</button></div><div class="form-grid"><div><label for="pType">Permit type</label><select id="pType"><option value="Hot Work">Hot Work</option><option value="Confined Space">Confined Space</option><option value="Work at Height">Work at Height</option><option value="Electrical Isolation">Electrical Isolation</option><option value="Excavation">Excavation</option><option value="Line Breaking">Line Breaking</option></select></div><div><label for="pArea">Location</label><input id="pArea" value="Production B"></div><div><label for="pHir">Linked HIRARC</label><select id="pHir" required></select></div><div><label for="pUntil">Valid until</label><input id="pUntil" type="datetime-local"></div></div><label for="pMember">Responsible organization member</label><input id="pMember" list="permitMembers" placeholder="Search organization members" autocomplete="off"><datalist id="permitMembers"></datalist><label for="pControls">Required controls</label><textarea id="pControls" required placeholder="Record verified controls and precautions"></textarea><label for="pFiles">Attachments</label><input id="pFiles" type="file" multiple><p class="note">Up to 10 files, 20 MB each.</p><p id="pError" role="alert"></p><div class="toolbar"><span></span><button type="button" class="btn primary" onclick="addPtw()">Create permit</button></div></div></dialog>
<dialog class="adapt-modal" id="drillModal" aria-labelledby="drillModal-title"><div class="modal-card"><div class="modal-head"><h3 id="drillModal-title">Schedule drill</h3><button aria-label="Close dialog" type="button" class="x" onclick="closeModal('drillModal')">×</button></div><div class="form-grid"><div><label for="dType">Drill type</label><select id="dType"><option value="Fire / evacuation">Fire / evacuation</option><option value="Chemical spill">Chemical spill</option><option value="Medical emergency">Medical emergency</option><option value="Rescue / confined space">Rescue / confined space</option><option value="Custom">Custom</option></select><label for="dTypeCustom">Custom drill type (when selected)</label><input id="dTypeCustom" placeholder="Enter custom drill type"></div><div><label for="dDate">Date</label><input id="dDate" type="date" value="2026-11-03"></div></div><label for="dDesc">Scenario / objective</label><textarea id="dDesc">Test alarm, evacuation time, headcount and communication with ERT.</textarea><div class="toolbar"><span></span><button type="button" class="btn primary" onclick="addDrill()">Schedule drill</button></div></div></dialog>
<dialog class="adapt-modal" id="incidentModal" aria-labelledby="incidentModal-title"><div class="modal-card"><div class="modal-head"><h3 id="incidentModal-title">Report incident / near miss</h3><button aria-label="Close dialog" type="button" class="x" onclick="closeModal('incidentModal')">×</button></div><div class="form-grid"><div><label for="iType">Type</label><select id="iType"><option value="Near Miss">Near Miss</option><option value="First Aid">First Aid</option><option value="Medical Treatment">Medical Treatment</option><option value="Lost Time Injury">Lost Time Injury</option><option value="Property Damage">Property Damage</option></select></div><div><label for="iArea">Area</label><input id="iArea" placeholder="Incident location"></div></div><label for="iText">What happened?</label><textarea id="iText" placeholder="Describe what happened" required></textarea><label for="iFiles">Evidence attachments</label><input id="iFiles" type="file" multiple><p class="note">Up to 10 files, 20 MB each.</p><p id="iError" role="alert"></p><div class="callout"><strong>Adaptive follow-up:</strong> HIRARC review + corrective action + toolbox talk + traffic-management review.</div><div class="toolbar"><span></span><button type="button" class="btn primary" onclick="addIncident()">Submit report</button></div></div></dialog>
<dialog class="adapt-modal" id="evidenceModal" aria-labelledby="evidenceTitle"><div class="modal-card"><div class="toolbar"><h3 id="evidenceTitle">Connected Evidence Index</h3><button aria-label="Close dialog" type="button" class="btn" onclick="closeModal('evidenceModal')">×</button></div><p class="note">This summary is generated from the current prototype records, not an official certification report.</p><div class="list" id="evidenceIndex"></div><div class="toolbar"><span></span><button type="button" class="btn" onclick="go('legal');closeModal('evidenceModal')">Open legal register</button><button type="button" class="btn teal" onclick="window.print()">Print current view</button></div></div></dialog>
<dialog class="adapt-modal" id="companyDetailsModal" aria-labelledby="companyDetailsTitle">
  <div class="modal-card company-details-dialog">
    <div class="modal-head"><div><h3 id="companyDetailsTitle">Edit company details</h3><p class="company-modal-note">Update your company profile. Changes will appear across Adapt360 after you save.</p></div><button type="button" class="x" onclick="closeModal('companyDetailsModal')" aria-label="Close dialog">×</button></div>
    <form id="companyDetailsForm" onsubmit="event.preventDefault();saveCompanyDetails()">
      <div class="form-grid">
        <div><label for="editCompanyName">Company name *</label><input id="editCompanyName" required autocomplete="organization"></div>
        <div><label for="editIndustry">Industry / business sector *</label><input id="editIndustry" list="editIndustryChoices" required placeholder="Type any industry"><datalist id="editIndustryChoices"><option value="Manufacturing"></option><option value="Construction"></option><option value="Logistics"></option><option value="Food Manufacturing"></option><option value="Retail / Services"></option><option value="Plantation"></option><option value="Oil & Gas"></option><option value="Healthcare"></option><option value="Hospitality"></option></datalist></div>
        <div><label for="editEmployees">Number of employees *</label><input id="editEmployees" type="number" min="1" step="1" required></div>
        <div><label for="editSite">Primary site / location *</label><input id="editSite" required placeholder="e.g. Miri, Sarawak"></div>
        <div><label for="editCompanyRegistration">Company registration number</label><input id="editCompanyRegistration" placeholder="Optional"></div>
        <div><label for="editCompanyPhone">Telephone</label><input id="editCompanyPhone" type="tel" placeholder="Optional"></div>
        <div><label for="editCompanyEmail">Company email</label><input id="editCompanyEmail" type="email" placeholder="Optional"></div>
        <div><label for="editCompanyAddress">Company address</label><textarea id="editCompanyAddress" rows="2" placeholder="Optional"></textarea></div>
      </div>
      <p class="company-modal-note">Updating employee count, industry or activities may change Adapt360's suggested OSH requirements. Your other records are retained.</p>
      <div class="toolbar company-modal-actions"><button type="button" class="btn" onclick="closeModal('companyDetailsModal')">Cancel</button><button type="submit" class="btn primary">Save company details</button></div>
    </form>
  </div>
</dialog>
@endverbatim
